__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"marketplaceDocument",{enumerable:!0,get:function(){return t}});var n=r(d[0]),s=r(d[1]);const t=(0,n.publishedDocument)({id:"marketplace",slug:"marketplace",title:"Fonctionnement de la marketplace Croki",shortTitle:"Fonctionnement Croki",sections:[{heading:"1. Pr\xe9sentation de Croki",paragraphs:[`${s.LEGAL_TRADE_NAME} est une plateforme num\xe9rique \xe9dit\xe9e et exploit\xe9e par ${s.LEGAL_OPERATOR_NAME}.`,"Croki permet aux consommateurs de d\xe9couvrir des professionnels partenaires de l\u2019alimentation, de consulter leurs \xe9tablissements et leurs offres et, lorsqu\u2019ils disposent d\u2019un compte, de commander des produits \xe0 emporter en click & collect.","Croki est accessible notamment au moyen de son site web, de sa PWA et de ses applications mobiles.","Croki ne fournit pas de service de livraison."]},{heading:"2. Nature du service",paragraphs:[`${s.LEGAL_OPERATOR_NAME} fournit le service num\xe9rique d\u2019interm\xe9diation ${s.LEGAL_TRADE_NAME}.`,"Croki met \xe0 disposition l\u2019infrastructure permettant notamment le r\xe9f\xe9rencement des Professionnels et de leurs \xe9tablissements, la pr\xe9sentation des offres, la recherche, le panier, la transmission des Commandes, leur suivi, le paiement, les notifications, les avis et le support.","Croki n\u2019exploite pas les \xe9tablissements r\xe9f\xe9renc\xe9s et ne pr\xe9pare pas les produits alimentaires vendus par les Professionnels.","Croki n\u2019est pas un service de livraison.","Croki n\u2019est pas le logiciel comptable ou le syst\xe8me de gestion comptable du Professionnel."]},{heading:"3. Qui peut proposer une offre sur Croki",paragraphs:["Les offres accessibles \xe0 la commande sur Croki sont propos\xe9es par des Professionnels.","Croki n\u2019est pas une place de march\xe9 permettant \xe0 des consommateurs ou particuliers de vendre des produits entre eux.","Un Professionnel doit disposer d\u2019un Compte Pro et d\u2019un \xc9tablissement remplissant les conditions n\xe9cessaires \xe0 son activation avant de pouvoir proposer des Commandes au public.","La qualit\xe9 professionnelle du vendeur est indiqu\xe9e dans le Service au moyen des informations disponibles sur l\u2019\xc9tablissement et dans le parcours de Commande."]},{heading:"4. Identit\xe9 du vendeur",paragraphs:["Chaque offre propos\xe9e \xe0 la commande est rattach\xe9e \xe0 un Professionnel identifi\xe9.","Croki met \xe0 disposition du Client les informations permettant d\u2019identifier le Professionnel vendeur conform\xe9ment aux informations fournies par celui-ci et aux exigences l\xe9gales applicables.","Ces informations peuvent notamment comprendre son nom ou sa d\xe9nomination sociale, son nom commercial, son adresse ou son \xe9tablissement, ses coordonn\xe9es de contact ainsi que ses informations d\u2019immatriculation lorsqu\u2019elles sont applicables.","Le Client peut ainsi identifier le Professionnel avec lequel il conclut la vente des produits."]},{heading:"5. R\xf4le du Professionnel",paragraphs:["Le Professionnel d\xe9termine les produits qu\u2019il souhaite commercialiser sur Croki.","Il renseigne et maintient \xe0 jour notamment son catalogue, ses produits, descriptions, prix, options, disponibilit\xe9s, horaires, lieux de retrait, photographies et informations relatives aux allerg\xe8nes.","Le Professionnel d\xe9cide d\u2019accepter ou de refuser chaque demande de Commande qui lui est transmise.","Lorsqu\u2019il accepte une Commande, il pr\xe9pare les produits et assure leur remise au Client au lieu de retrait indiqu\xe9.","Le Professionnel demeure responsable des obligations qui lui incombent en qualit\xe9 de vendeur et de professionnel de l\u2019alimentation."]},{heading:"6. R\xf4le de FOODTECH SOLUTIONS / Croki",paragraphs:[`${s.LEGAL_OPERATOR_NAME} con\xe7oit, \xe9dite et exploite ${s.LEGAL_TRADE_NAME}.`,"Croki permet notamment la mise en relation, l\u2019affichage des offres, la constitution du panier, le calcul et la v\xe9rification technique des montants, la transmission des Commandes, leur suivi et l\u2019orchestration technique des paiements.","Croki fournit \xe9galement les fonctionnalit\xe9s permettant aux Professionnels de g\xe9rer leur pr\xe9sence sur la plateforme et leurs Commandes.","Croki n\u2019est pas le vendeur des produits alimentaires lorsque le Professionnel est identifi\xe9 comme vendeur.","Les obligations propres de FOODTECH SOLUTIONS au titre du service Croki demeurent applicables ind\xe9pendamment des obligations du Professionnel vendeur."]},{heading:"7. Contrats conclus au moyen de Croki",paragraphs:["Le fonctionnement de Croki implique plusieurs relations contractuelles distinctes.","La vente des produits alimentaires est conclue entre le Client et le Professionnel identifi\xe9 comme vendeur de la Commande.",`Le service num\xe9rique Croki fourni au Client, comprenant notamment le service d\u2019interm\xe9diation associ\xe9 aux Frais de service applicables, rel\xe8ve de la relation entre le Client et ${s.LEGAL_OPERATOR_NAME}.`,`La relation entre le Professionnel partenaire et ${s.LEGAL_OPERATOR_NAME} est r\xe9gie par les Conditions g\xe9n\xe9rales Professionnels partenaires.`,"Les CGU et CGV Client pr\xe9cisent les droits et obligations applicables au parcours Client."]},{heading:"8. R\xe9f\xe9rencement des Professionnels",paragraphs:["La cr\xe9ation d\u2019un Compte Pro ne garantit pas automatiquement le r\xe9f\xe9rencement public d\u2019un \xc9tablissement.","Pour \xeatre r\xe9f\xe9renc\xe9 et pouvoir recevoir des Commandes, le Professionnel doit notamment disposer d\u2019un compte autoris\xe9, fournir les informations requises, exploiter une activit\xe9 compatible avec Croki et respecter les Conditions Pro.","L\u2019\xc9tablissement doit disposer des informations n\xe9cessaires \xe0 son exploitation sur Croki et \xeatre dans un \xe9tat permettant son activation.","Lorsque le paiement en ligne est n\xe9cessaire, l\u2019infrastructure de paiement du Professionnel doit \xeatre suffisamment configur\xe9e pour permettre le traitement des Commandes.","Croki peut v\xe9rifier les informations professionnelles et justificatifs n\xe9cessaires avant l\u2019activation ou au cours de la relation."]},{heading:"9. D\xe9r\xe9f\xe9rencement",paragraphs:["Un \xc9tablissement ou une offre peut \xeatre temporairement ou d\xe9finitivement d\xe9r\xe9f\xe9renc\xe9 lorsqu\u2019il ne remplit plus les conditions n\xe9cessaires \xe0 sa pr\xe9sence sur Croki.","Les motifs peuvent notamment comprendre une demande du Professionnel, la fermeture de l\u2019\xe9tablissement, des informations inexactes ou devenues obsol\xe8tes, une violation des Conditions Pro, un contenu illicite, une fraude, un risque sanitaire, un incident de s\xe9curit\xe9, une obligation l\xe9gale ou l\u2019impossibilit\xe9 de traiter correctement les paiements.","Lorsque les r\xe8gles applicables l\u2019exigent, Croki informe le Professionnel des motifs de la restriction, suspension ou du d\xe9r\xe9f\xe9rencement et des voies de contestation disponibles.","Les r\xe8gles d\xe9taill\xe9es applicables aux Professionnels figurent dans les Conditions Pro."]},{heading:"10. Caract\xe8re non exhaustif du r\xe9f\xe9rencement",paragraphs:["Croki ne r\xe9f\xe9rence pas n\xe9cessairement l\u2019ensemble des foodtrucks, restaurants ou commerces alimentaires existant dans une zone g\xe9ographique.","Les r\xe9sultats pr\xe9sent\xe9s correspondent uniquement aux \xc9tablissements effectivement r\xe9f\xe9renc\xe9s sur Croki et r\xe9pondant aux conditions de la recherche ou des filtres appliqu\xe9s.","L\u2019absence d\u2019un Professionnel dans les r\xe9sultats ne signifie donc pas qu\u2019aucun autre Professionnel comparable n\u2019existe dans la zone concern\xe9e."]},{heading:"11. Recherche et filtres",paragraphs:["L\u2019utilisateur peut limiter les r\xe9sultats affich\xe9s au moyen des outils de recherche et des filtres propos\xe9s par Croki.","Selon les fonctionnalit\xe9s disponibles, ces crit\xe8res peuvent notamment concerner la ville ou la zone g\xe9ographique, la distance, le type d\u2019\xe9tablissement, la cat\xe9gorie ou cuisine recherch\xe9e et l\u2019\xe9tat d\u2019ouverture ou de disponibilit\xe9.","Un filtre agit d\u2019abord sur l\u2019ensemble des r\xe9sultats \xe9ligibles : les \xe9tablissements qui ne correspondent pas au crit\xe8re s\xe9lectionn\xe9 peuvent \xeatre exclus de la liste avant l\u2019application de l\u2019ordre de classement.","Les filtres s\xe9lectionn\xe9s par l\u2019utilisateur ont donc une influence directe sur les offres qu\u2019il voit."]},{heading:"12. Classement par d\xe9faut",paragraphs:["Lorsque plusieurs \xc9tablissements r\xe9pondent \xe0 la recherche du Client, Croki les ordonne selon les principaux param\xe8tres disponibles pour la recherche concern\xe9e.","Dans le fonctionnement actuel de Croki, le principal param\xe8tre de classement g\xe9ographique est la proximit\xe9 entre la localisation utilis\xe9e pour la recherche et le lieu d\xe9clar\xe9 de l\u2019\xc9tablissement.","La note moyenne issue des avis Croki peut \xe9galement contribuer \xe0 l\u2019ordre des r\xe9sultats lorsque cette information est disponible et utilis\xe9e dans le classement concern\xe9.","Les filtres express\xe9ment s\xe9lectionn\xe9s par l\u2019utilisateur ont priorit\xe9 pour d\xe9terminer les \xe9tablissements \xe9ligibles \xe0 l\u2019affichage avant leur classement.","Lorsque certains param\xe8tres ne sont pas disponibles, notamment lorsque l\u2019utilisateur ne fournit pas de localisation, Croki utilise les informations restantes disponibles pour pr\xe9senter les r\xe9sultats correspondant \xe0 la recherche.","Les param\xe8tres techniques utilis\xe9s uniquement pour garantir un ordre stable entre des r\xe9sultats \xe9quivalents ne constituent pas un m\xe9canisme de promotion commerciale."]},{heading:"13. Importance relative des principaux param\xe8tres",paragraphs:["L\u2019importance des param\xe8tres peut \xeatre r\xe9sum\xe9e comme suit :","1. Les crit\xe8res et filtres express\xe9ment choisis par l\u2019utilisateur d\xe9terminent d\u2019abord les offres \xe9ligibles \xe0 sa recherche.","2. Lorsque la localisation est disponible et que la recherche repose sur la proximit\xe9, la distance constitue le principal crit\xe8re d\u2019ordre g\xe9ographique.","3. Lorsque la fonctionnalit\xe9 concern\xe9e utilise les \xe9valuations, la note des \xe9tablissements peut ensuite contribuer \xe0 d\xe9partager ou ordonner les r\xe9sultats.","4. Des crit\xe8res techniques neutres peuvent \xeatre utilis\xe9s uniquement pour stabiliser l\u2019ordre lorsque plusieurs r\xe9sultats sont \xe9quivalents.","Cette pr\xe9sentation d\xe9crit les principaux param\xe8tres et non chaque r\xe8gle technique interne ou m\xe9canisme de s\xe9curit\xe9 utilis\xe9 par Croki."]},{heading:"14. G\xe9olocalisation",paragraphs:["Lorsque l\u2019utilisateur autorise Croki \xe0 utiliser sa localisation, celle-ci peut \xeatre utilis\xe9e pour rechercher et ordonner les \xe9tablissements situ\xe9s \xe0 proximit\xe9.","Le refus de la g\xe9olocalisation n\u2019emp\xeache pas n\xe9cessairement l\u2019utilisation de Croki : une recherche fond\xe9e sur une ville ou une autre localisation renseign\xe9e peut \xeatre propos\xe9e.","Croki n\u2019utilise pas la position du Client afin de constituer un historique publicitaire de ses d\xe9placements.","Les traitements de g\xe9olocalisation sont d\xe9taill\xe9s dans la Politique de confidentialit\xe9."]},{heading:"15. Absence de placement pay\xe9",paragraphs:["Dans le fonctionnement actuel de Croki, un Professionnel ne peut pas payer FOODTECH SOLUTIONS afin d\u2019obtenir automatiquement une meilleure position dans les r\xe9sultats de recherche.","La commission normalement due par les Professionnels au titre des Commandes ne leur accorde pas un meilleur classement.","Les Frais de service pay\xe9s par les Clients n\u2019influencent pas non plus le classement.","Croki ne propose actuellement pas de fonctionnalit\xe9 de placement sponsoris\xe9 ou de mise en avant payante modifiant le rang des r\xe9sultats.","Si une telle fonctionnalit\xe9 \xe9tait introduite ult\xe9rieurement, son influence sur le classement et le caract\xe8re publicitaire de l\u2019offre concern\xe9e seraient clairement signal\xe9s avant sa mise en service."]},{heading:"16. Relations contractuelles ou capitalistiques",paragraphs:["Le seul fait qu\u2019un Professionnel ait conclu un contrat avec FOODTECH SOLUTIONS afin d\u2019utiliser Croki n\u2019entra\xeene pas, dans le fonctionnement actuel du Service, une am\xe9lioration de son classement par rapport aux autres Professionnels \xe9ligibles.","Lorsqu\u2019une relation contractuelle particuli\xe8re, un lien capitalistique ou une r\xe9mun\xe9ration devait influencer le r\xe9f\xe9rencement ou le classement d\u2019un r\xe9sultat, Croki en informerait clairement les utilisateurs conform\xe9ment aux r\xe8gles applicables.","Aucun r\xe9sultat ne doit \xeatre pr\xe9sent\xe9 comme neutre lorsqu\u2019il b\xe9n\xe9ficie en r\xe9alit\xe9 d\u2019un avantage de classement directement li\xe9 \xe0 une r\xe9mun\xe9ration."]},{heading:"17. \xc9tablissements de d\xe9monstration et pr\xe9-lancement",paragraphs:["Pendant les phases de d\xe9veloppement ou de pr\xe9-lancement, Croki peut utiliser des \xe9tablissements ou donn\xe9es de d\xe9monstration afin de tester et pr\xe9senter le fonctionnement du Service.","Les contenus de d\xe9monstration accessibles au public doivent \xeatre identifiables comme tels lorsqu\u2019ils ne correspondent pas \xe0 une v\xe9ritable offre commerciale disponible \xe0 la Commande.","Les donn\xe9es de d\xe9monstration ne doivent pas \xeatre confondues avec une offre r\xe9ellement propos\xe9e par un Professionnel.","Lors de l\u2019exploitation commerciale normale de Croki, les \xe9tablissements de d\xe9monstration ne b\xe9n\xe9ficient pas d\u2019une priorit\xe9 commerciale artificielle dans le classement des v\xe9ritables Professionnels."]},{heading:"18. Prix des produits",paragraphs:["Les prix des produits sont d\xe9termin\xe9s et renseign\xe9s par le Professionnel vendeur.","Les prix pr\xe9sent\xe9s au consommateur sont affich\xe9s en euros toutes taxes comprises lorsque la TVA est applicable.","Le Professionnel reste responsable de la fiscalit\xe9 applicable aux produits qu\u2019il commercialise.","Le montant d\xe9finitif applicable \xe0 une Commande est pr\xe9sent\xe9 au Client avant son engagement."]},{heading:"19. Frais de service Client",paragraphs:["Croki facture actuellement au Client des Frais de service de 0,50 \u20ac TTC par Commande lorsque ces frais sont applicables.",`Ces Frais de service r\xe9mun\xe8rent le service num\xe9rique fourni par ${s.LEGAL_OPERATOR_NAME} au Client.`,"Ils sont pr\xe9sent\xe9s s\xe9par\xe9ment avant la validation de la Commande et sont int\xe9gr\xe9s au total que le Client doit examiner avant de s\u2019engager.","Le montant applicable est celui pr\xe9sent\xe9 au Client au moment de la validation de sa Commande."]},{heading:"20. Commission Professionnel",paragraphs:[`Le Professionnel verse actuellement \xe0 ${s.LEGAL_OPERATOR_NAME} une commission de 3 % HT calcul\xe9e sur le montant des produits des Commandes concern\xe9es, selon les Conditions Pro applicables.`,"La TVA applicable \xe0 cette commission est ajout\xe9e conform\xe9ment aux r\xe8gles fiscales applicables.","Cette commission est support\xe9e par le Professionnel et n\u2019est pas ajout\xe9e comme une ligne suppl\xe9mentaire au prix des produits pay\xe9 par le Client.","La commission professionnelle n\u2019entre pas dans le calcul du classement des \xe9tablissements."]},{heading:"21. Paiement",paragraphs:["Les Commandes Croki sont pay\xe9es en ligne au moyen de l\u2019infrastructure Stripe et Stripe Connect utilis\xe9e par Croki et les Professionnels.","Selon les moyens disponibles sur l\u2019appareil et le compte concern\xe9, le paiement peut notamment \xeatre r\xe9alis\xe9 par carte bancaire, Apple Pay ou Google Pay.","Une authentification bancaire suppl\xe9mentaire telle que 3-D Secure peut \xeatre demand\xe9e par le prestataire de paiement ou l\u2019\xe9tablissement bancaire.","Croki ne stocke pas les num\xe9ros complets de cartes bancaires."]},{heading:"22. Gestion de la transaction financi\xe8re",paragraphs:["Stripe assure le traitement technique des paiements r\xe9alis\xe9s dans Croki.","La vente des produits est associ\xe9e au Professionnel vendeur au moyen de l\u2019infrastructure Stripe Connect utilis\xe9e par Croki.","FOODTECH SOLUTIONS per\xe7oit la commission qui lui est due au titre de sa relation avec le Professionnel conform\xe9ment aux Conditions Pro.","Les Frais de service Croki pay\xe9s par le Client r\xe9mun\xe8rent s\xe9par\xe9ment le Service Croki.","Croki ne propose pas de portefeuille \xe9lectronique permettant aux utilisateurs de conserver librement une cagnotte ou de transf\xe9rer des fonds entre eux.","Croki ne permet pas aux utilisateurs de transf\xe9rer de l\u2019argent directement d\u2019un compte utilisateur \xe0 un autre."]},{heading:"23. D\xe9roulement d\u2019une Commande",paragraphs:["Le Client s\xe9lectionne un \xc9tablissement et les produits qu\u2019il souhaite commander.","Une Commande concerne un seul \xc9tablissement.","Avant son engagement, le Client consulte un r\xe9capitulatif comprenant notamment le Professionnel ou l\u2019\xc9tablissement concern\xe9, les produits, quantit\xe9s et options, le lieu de retrait, les prix, les Frais de service applicables et le montant total.","Le Client transmet ensuite sa demande et accomplit les op\xe9rations de paiement n\xe9cessaires.","La demande est transmise au Professionnel afin qu\u2019il puisse l\u2019accepter ou la refuser."]},{heading:"24. Acceptation par le Professionnel",paragraphs:["La demande du Client reste en attente tant que le Professionnel ne l\u2019a pas accept\xe9e ou refus\xe9e et que le d\xe9lai applicable n\u2019est pas expir\xe9.","La vente des produits est form\xe9e lorsque le Professionnel accepte la Commande conform\xe9ment aux CGV Client.","L\u2019acceptation confirme que le Professionnel s\u2019engage \xe0 pr\xe9parer les produits command\xe9s.","Le Client peut suivre l\u2019\xe9volution de sa Commande dans Croki."]},{heading:"25. Refus ou absence de r\xe9ponse",paragraphs:["Le Professionnel peut refuser une demande lorsqu\u2019il ne peut pas l\u2019ex\xe9cuter.","Une demande demeurant sans r\xe9ponse pendant le d\xe9lai pr\xe9vu par Croki expire automatiquement.","Dans ces situations, la vente alimentaire n\u2019est pas form\xe9e.","Les op\xe9rations de paiement qui ne doivent plus \xeatre ex\xe9cut\xe9es sont annul\xe9es, lib\xe9r\xe9es ou rembours\xe9es selon leur \xe9tat.","Croki ne conserve pas les Frais de service d\u2019une Commande qui n\u2019a pas \xe9t\xe9 accept\xe9e lorsque ces frais ne sont plus dus."]},{heading:"26. Pr\xe9paration et retrait",paragraphs:["Apr\xe8s l\u2019acceptation et lorsque les conditions de paiement permettent l\u2019ex\xe9cution de la Commande, le Professionnel pr\xe9pare les produits.","Le Professionnel peut indiquer dans Croki que la Commande est en pr\xe9paration puis qu\u2019elle est pr\xeate.","Le Client se rend au lieu de retrait communiqu\xe9 pour r\xe9cup\xe9rer sa Commande.","La remise physique des produits est effectu\xe9e par le Professionnel et non par Croki.","Croki ne r\xe9alise aucune livraison au domicile du Client."]},{heading:"27. Produits et allerg\xe8nes",paragraphs:["Les informations relatives aux produits, ingr\xe9dients et allerg\xe8nes sont fournies par le Professionnel vendeur.","Croki met \xe0 disposition des outils permettant au Professionnel de structurer et pr\xe9senter ces informations.","Le Professionnel demeure responsable de l\u2019exactitude et de l\u2019actualisation des informations relatives aux produits qu\u2019il pr\xe9pare et commercialise.","Croki ne doit pas transformer une donn\xe9e non v\xe9rifi\xe9e communiqu\xe9e par le Professionnel en garantie d\u2019absence d\u2019un allerg\xe8ne."]},{heading:"28. Avis",paragraphs:["Croki permet aux Clients remplissant les conditions du Service de publier un avis relatif \xe0 une exp\xe9rience de consommation.","Dans le fonctionnement actuel, un avis Croki est li\xe9 \xe0 une Commande dont le retrait a \xe9t\xe9 confirm\xe9 et un seul avis peut \xeatre d\xe9pos\xe9 pour une m\xeame Commande.","Le Professionnel peut r\xe9pondre \xe0 un avis lorsqu\u2019une fonctionnalit\xe9 de r\xe9ponse est propos\xe9e.","Croki peut contr\xf4ler et mod\xe9rer les avis conform\xe9ment aux CGU et aux r\xe8gles relatives aux avis.","Les informations relatives au contr\xf4le, au classement, \xe0 la publication et \xe0 la conservation des avis sont mises \xe0 disposition du public conform\xe9ment aux r\xe8gles applicables."]},{heading:"29. Signalement de contenus",paragraphs:["Croki permet de signaler certains contenus, avis, \xe9tablissements, produits ou comportements susceptibles d\u2019\xeatre illicites ou contraires aux r\xe8gles du Service.","Le signalement doit comporter les informations permettant d\u2019identifier le contenu ou la situation concern\xe9e et d\u2019en comprendre le motif.","Croki examine les signalements selon leur nature et peut prendre une mesure de mod\xe9ration lorsqu\u2019elle est justifi\xe9e.","Selon les circonstances, une mesure peut notamment consister \xe0 masquer un contenu, demander une correction, restreindre une fonctionnalit\xe9, suspendre un \xc9tablissement ou prendre toute mesure n\xe9cessaire au respect de la loi ou \xe0 la s\xe9curit\xe9 du Service."]},{heading:"30. R\xe9clamations Client",paragraphs:["Le Client peut contacter le support Croki pour une difficult\xe9 relative au fonctionnement du Service ou \xe0 une Commande.",`FOODTECH SOLUTIONS peut \xe9galement \xeatre contact\xe9e \xe0 l\u2019adresse ${s.LEGAL_SLOT.email}.`,"Lorsqu\u2019une difficult\xe9 concerne directement les produits, leur pr\xe9paration ou leur remise, le Professionnel vendeur demeure responsable des obligations qui lui incombent.","Croki peut faciliter les \xe9changes entre le Client et le Professionnel lorsque cela est n\xe9cessaire au traitement de la situation.","Les CGV Client pr\xe9cisent les r\xe8gles applicables aux annulations, remboursements et r\xe9clamations."]},{heading:"31. R\xe9clamations Professionnel",paragraphs:["Le Professionnel peut utiliser le Support Pro pour signaler un probl\xe8me relatif au Service, \xe0 une Commande, \xe0 une d\xe9cision de mod\xe9ration, \xe0 son \xc9tablissement ou \xe0 sa relation avec Croki.","Les conditions de restriction, suspension, d\xe9r\xe9f\xe9rencement, r\xe9siliation et contestation sont d\xe9taill\xe9es dans les Conditions Pro.","La pr\xe9sente page ne remplace pas les m\xe9canismes de recours ou de r\xe8glement des diff\xe9rends pr\xe9vus par les Conditions Pro ou par la l\xe9gislation applicable."]},{heading:"32. Assurances et garanties propos\xe9es par Croki",paragraphs:["Croki ne propose actuellement au Client aucune assurance optionnelle propre \xe0 la marketplace dans le cadre d\u2019une Commande.","Croki ne fournit pas de garantie commerciale suppl\xe9mentaire sur les produits alimentaires vendus par les Professionnels.","Cette absence de garantie commerciale Croki ne prive ni le Client ni le Professionnel des droits, garanties ou responsabilit\xe9s r\xe9sultant directement de la loi ou de leurs contrats applicables."]},{heading:"33. Donn\xe9es personnelles",paragraphs:["Le fonctionnement de Croki implique le traitement de certaines donn\xe9es personnelles n\xe9cessaires notamment aux comptes, Commandes, paiements, support, g\xe9olocalisation optionnelle et gestion des Professionnels.","Les finalit\xe9s, bases juridiques, destinataires, dur\xe9es de conservation, transferts \xe9ventuels et droits des personnes sont d\xe9taill\xe9s dans la Politique de confidentialit\xe9.","Les cookies, stockages locaux et technologies similaires sont d\xe9taill\xe9s dans la Politique cookies et traceurs."]},{heading:"34. Documents applicables",paragraphs:["Le fonctionnement de Croki doit \xeatre lu avec les autres documents applicables au Service.","Les Visiteurs et Clients sont notamment concern\xe9s par les CGU.","Les Clients qui passent une Commande sont \xe9galement concern\xe9s par les CGV Client.","Les Professionnels partenaires sont soumis aux Conditions Pro.","La Politique de confidentialit\xe9 et la Politique cookies et traceurs d\xe9crivent les traitements de donn\xe9es et technologies associ\xe9es.","Les Mentions l\xe9gales identifient FOODTECH SOLUTIONS et les principaux prestataires d\u2019h\xe9bergement concern\xe9s."]},{heading:"35. \xc9volution du fonctionnement",paragraphs:["Croki peut faire \xe9voluer son fonctionnement, ses fonctionnalit\xe9s, ses param\xe8tres de classement ou son mod\xe8le \xe9conomique.","Lorsque cette \xe9volution affecte une information devant l\xe9galement \xeatre port\xe9e \xe0 la connaissance des utilisateurs ou Professionnels, la pr\xe9sente rubrique et les documents concern\xe9s sont mis \xe0 jour.","Si une r\xe9mun\xe9ration, un placement sponsoris\xe9 ou un lien particulier devait \xe0 l\u2019avenir influencer le classement, cette influence serait indiqu\xe9e clairement dans cette rubrique et \xe0 proximit\xe9 des r\xe9sultats lorsque la r\xe9glementation l\u2019exige.","Une modification de la pr\xe9sente page ne modifie pas r\xe9troactivement les conditions applicables \xe0 une Commande d\xe9j\xe0 conclue."]},{heading:"36. Contact",paragraphs:[`\xc9diteur et exploitant : ${s.LEGAL_OPERATOR_NAME}.`,`Service : ${s.LEGAL_TRADE_NAME}.`,`Adresse : ${s.LEGAL_SLOT.registeredOffice}.`,`E-mail : ${s.LEGAL_SLOT.email}.`,`T\xe9l\xe9phone : ${s.LEGAL_SLOT.phone}.`]}]})},1531,[1630,1228]);